    id, request_id, diagram_id, user_id, agent_id, session_id, request_type, credential_source, model_credential_id,
    status, error_class, started_at, completed_at, latency_ms
)
VALUES (
    #{id}, #{requestId}, #{diagramId}, #{userId}, #{agentId}, #{sessionId}, #{requestType}, #{credentialSource}, #{modelCredentialId},
    #{status}, #{errorClass}, #{startedAt}, #{completedAt}, #{latencyMs}
)

mapper.update:
UPDATE agent_run
SET status = #{status},
    error_class = #{errorClass},
    completed_at = #{completedAt},
    latency_ms = #{latencyMs}
WHERE id = #{id}

