mapper.select:
SELECT
    COALESCE(SUM(CASE WHEN r.credential_source = 'PLATFORM' THEN 1 ELSE 0 END), 0) AS platformRunCount,
    COALESCE(SUM(CASE WHEN r.credential_source = 'USER_KEY' THEN 1 ELSE 0 END), 0) AS userKeyRunCount,
    (
        SELECT COALESCE(SUM(CASE WHEN c.credential_source = 'PLATFORM' THEN 1 ELSE 0 END), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
    ) AS platformLlmCallCount,
    (
        SELECT COALESCE(SUM(CASE WHEN c.credential_source = 'USER_KEY' THEN 1 ELSE 0 END), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
    ) AS userKeyLlmCallCount,
    (
        SELECT COALESCE(COUNT(*), 0)
        FROM agent_tool_call t
        WHERE t.user_id = #{userId}
    ) AS toolCallCount,
    (
        SELECT COALESCE(SUM(c.total_tokens), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
    ) AS knownTotalTokens,
    (
        SELECT COALESCE(COUNT(*), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
          AND c.total_tokens IS NULL
    ) AS unknownTokenLlmCallCount
FROM agent_run r
WHERE r.user_id = #{userId}

SELECT r.id, r.request_id, r.diagram_id, r.user_id, r.agent_id, r.session_id, r.request_type, r.credential_source, r.model_credential_id, r.status, r.error_class, r.started_at, r.completed_at, r.latency_ms, (SELECT COALESCE(COUNT(*), 0) FROM agent_run_step s WHERE s.run_id = r.id) AS step_count, (SELECT COALESCE(COUNT(*), 0) FROM agent_llm_call c WHERE c.run_id = r.id) AS llm_call_count, (SELECT COALESCE(COUNT(*), 0) FROM agent_tool_call t WHERE t.run_id = r.id) AS tool_call_count, (SELECT COALESCE(COUNT(*), 0) FROM agent_trace_event e WHERE e.run_id = r.id) AS trace_event_count, (SELECT COALESCE(SUM(c.total_tokens), 0) FROM agent_llm_call c WHERE c.run_id = r.id) AS known_total_tokens FROM agent_run r
AND r.status = #{status} AND r.user_id = #{userId} AND r.agent_id = #{agentId}
ORDER BY r.started_at DESC, r.id DESC LIMIT #{limit} OFFSET #{offset}

